#include <iostream>
#include <string>
#include <regex>
using namespace std;

int main() {
    string s;
    while (cin >> s) {
        // Replace first occurrence of "at" with "@"
        size_t pos_at = s.find("at");
        if (pos_at != string::npos && pos_at > 0) { // must not be at index 0? Actually original starts from index 1, so we need to ensure we only replace if pos_at >= 1
            // But original only checks from i=1 onward, so "at" at index 0 is not replaced. We'll handle by scanning from index 1.
            // Better to simulate left-to-right: we'll build output manually using find.
        }
        // Simpler: use iterative find from position 1
        string out;
        out += s[0];
        size_t i = 1;
        bool at_replaced = false;
        while (i < s.size()) {
            size_t next_at = s.find("at", i);
            size_t next_dot = s.find("dot", i);
            // Choose the earliest occurrence
            if (!at_replaced && next_at != string::npos && (next_dot == string::npos || next_at < next_dot)) {
                // Append characters before "at"
                out.append(s, i, next_at - i);
                out += '@';
                at_replaced = true;
                i = next_at + 2;
            } else if (next_dot != string::npos && (next_at == string::npos || next_dot < next_at || at_replaced)) {
                out.append(s, i, next_dot - i);
                out += '.';
                i = next_dot + 3;
            } else {
                out.append(s, i);
                break;
            }
        }
        cout << out << endl;
    }
    return 0;
}
